package com.circlenet.domain.social.model;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="social_stories") public class SocialStoryEntity {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="author_user_id",nullable=false) private Long authorUserId; @Column(length=1000,nullable=false) private String caption=""; @Column(length=24,nullable=false) private String audience="RELATIONSHIPS"; @Column(name="media_key",nullable=false) private String mediaKey; @Column(name="media_name") private String mediaName; @Column(name="media_type",nullable=false) private String mediaType; @Column(name="media_size") private Long mediaSize; @Column(name="created_at",nullable=false) private Instant createdAt=Instant.now(); @Column(name="expires_at",nullable=false) private Instant expiresAt;
 public Long getId(){return id;} public Long getAuthorUserId(){return authorUserId;} public void setAuthorUserId(Long v){authorUserId=v;} public String getCaption(){return caption;} public void setCaption(String v){caption=v;} public String getAudience(){return audience;} public void setAudience(String v){audience=v;} public String getMediaKey(){return mediaKey;} public void setMediaKey(String v){mediaKey=v;} public String getMediaName(){return mediaName;} public void setMediaName(String v){mediaName=v;} public String getMediaType(){return mediaType;} public void setMediaType(String v){mediaType=v;} public Long getMediaSize(){return mediaSize;} public void setMediaSize(Long v){mediaSize=v;} public Instant getCreatedAt(){return createdAt;} public Instant getExpiresAt(){return expiresAt;} public void setExpiresAt(Instant v){expiresAt=v;}
}
